#include <cstdio>

namespace fish_tank {

// 缸里最多摆几排——按每排 per_row 条算，向上取整
int CeilDiv(int total, int per_row) {
    return (total + per_row - 1) / per_row;
}

}  // namespace fish_tank

int main() {
    printf("%d %d %d\n", fish_tank::CeilDiv(10, 3), fish_tank::CeilDiv(9, 3), fish_tank::CeilDiv(12, 4));
    return 0;
}

